{
  "name": "EMA 20/55 cross {{runSuffix}}",
  "description": "Long on fast crossing above slow, short on the inverse",
  "rule": {
    "version": 1,
    "indicators": [
      {
        "id": "fast",
        "type": "Ema",
        "params": {
          "period": 20
        }
      },
      {
        "id": "slow",
        "type": "Ema",
        "params": {
          "period": 55
        }
      }
    ],
    "entry": {
      "long": {
        "op": "CrossesAbove",
        "left": {
          "ref": "fast"
        },
        "right": {
          "ref": "slow"
        }
      },
      "short": {
        "op": "CrossesBelow",
        "left": {
          "ref": "fast"
        },
        "right": {
          "ref": "slow"
        }
      }
    },
    "stopLoss": {
      "kind": "Percent",
      "percent": 2
    }
  }
}
